-- WRONG: always returns zero rows, even when MiddleName IS NULL for many people
SELECT FirstName, MiddleName FROM Person.Person WHERE MiddleName = NULL;

-- CORRECT
SELECT FirstName, MiddleName FROM Person.Person WHERE MiddleName IS NULL;

-- Substituting a readable default instead of filtering
SELECT FirstName, ISNULL(MiddleName, '(none)') AS MiddleName FROM Person.Person;
